      emData[idx + 1] = emG;
      emData[idx + 2] = emB;
      emData[idx + 3] = 255;
      bumpData[idx] = bumpVal;
      bumpData[idx + 1] = bumpVal;
      bumpData[idx + 2] = bumpVal;
